INSERT INTO app_settings (setting_key,value) VALUES ('level_thresholds','{"minus_max": -2, "plus_min": 2}'),('value_tag_labels','{"L": {"-1": "穏やか", "0": "バランス", "1": "刺激"}, "C": {"-1": "納得", "0": "バランス", "1": "行動"}, "M": {"-1": "備える", "0": "バランス", "1": "今を充実"}}') ON DUPLICATE KEY UPDATE value=VALUES(value);
INSERT INTO result_texts (axis_id,level,body) VALUES (1,1,'好きなものには遠方への遠征や新しい体験も惜しまず、刺激を追いかける。'),(1,0,'新しい体験に心が動く一方、落ち着く習慣も手放さない。'),(1,-1,'使い慣れた道具やいつもの習慣を大切にし、穏やかな時間を楽しむ。'),(2,1,'気になったことは失敗を恐れすぎず決断し、まず大胆に動いて経験から考える。'),(2,0,'小さなことは思い切りよく、大きな決断は確かめてから進める。'),(2,-1,'条件や例外まで確認し、比べて納得してから決める。'),(3,1,'将来に回す予定のお金でも、今の体験や大切な人との時間に使う選択をする。'),(3,0,'今の楽しみも先の備えも大切にし、状況に応じて使い分ける。'),(3,-1,'今使う前に将来分を先取りし、先の選択肢を少しずつ増やす。');
