INSERT INTO speakers (id,speaker_key,name,photo_url,one_liner,area,job_title,intro_text,personality_text) VALUES (1,'ST0004','太田 悠人','/images/speakers/ST0004.webp','慎重に見えて好奇心旺盛。気になったら大胆に動く。','大牟田エリア','家計・貯蓄相談','慎重に見えて好奇心旺盛と言われます。休日は好きな音楽のライブを追いかけ、好きなもののためなら遠征もいといません。決めたら迷いを残したままでも、まず大胆に動きます。将来に残す予定のお金を調整して、今の体験に使うこともあります。','人柄は慎重に見えて好奇心旺盛。日頃は「お祝いごとは少し奮発する」という一面も。休日は音楽や旅行を楽しみます。44歳、仕事では小さな約束も守ることを大切にしています。');
