INSERT INTO speaker_episodes (episode_key,speaker_id,source_type,title,body,axis_id,direction,status) VALUES ('EP0010',1,'self','ツアーは、いちばん遠い会場で','好きなバンドのツアーは、わざといちばん遠い会場を選びます。知らない町の駅に降りると、開演前からもう楽しくなっています。',1,1,'published');
INSERT INTO speaker_episodes (episode_key,speaker_id,source_type,title,body,axis_id,direction,status) VALUES ('EP0011',1,'self','本棚を買ってから間取りを考えた','部屋を広くしたいと思った日に、大きな本棚を買いました。どこに置くかは、届いてから考えました。',2,1,'published');
INSERT INTO speaker_episodes (episode_key,speaker_id,source_type,title,body,axis_id,direction,status) VALUES ('EP0012',1,'self','その席は、今年しかない','好きなバンドの記念公演で、ステージに近い席を取りました。その月は外食せず自炊しましたが、、後悔はしていません。',3,1,'published');
INSERT INTO speakers (id,speaker_key,name,photo_url,one_liner,area,job_title,intro_text,personality_text) VALUES (2,'ST0039','中村 さくら','/images/speakers/ST0039.webp','大切な人との時間に奮発。気になったら大胆に動く。','西福岡エリア','資産形成相談','ユーモア好きと言われます。休日は行き慣れた店をゆっくり楽しみ、気に入った道具は長く使います。決めたら迷いを残したままでも、まず大胆に動きます。将来に残す予定のお金を調整して、今の体験に使うこともあります。','人柄はユーモア好き。日頃は「予定変更を楽しめる」という一面も。休日は食べ歩きやゲームを楽しみます。42歳、仕事では小さな約束も守ることを大切にしています。');
