INSERT INTO speaker_episodes (episode_key,speaker_id,source_type,title,body,axis_id,direction,status) VALUES ('EP0115',2,'self','誕生日も、近所の洋食屋','誕生日は、新しい店に行くより顔なじみの近所の洋食屋。座ると「いつもの？」と聞かれるから、メニューはほとんど開かない。',1,-1,'published');
INSERT INTO speaker_episodes (episode_key,speaker_id,source_type,title,body,axis_id,direction,status) VALUES ('EP0116',2,'self','決まらないので手を挙げた','集まりの幹事がなかなか決まらず、誰も立候補せず沈黙が長くなったので、手を挙げた。何をするかは、押さえた会場を見ながら考えた。',2,1,'published');
INSERT INTO speaker_episodes (episode_key,speaker_id,source_type,title,body,axis_id,direction,status) VALUES ('EP0117',2,'self','子どもの誕生日は、行きたい店で','子どもの誕生日は、本人が行きたいと言った少し高いお店にしました。その月にためる分は減りましたが、デザートの写真をいまも見返しています。',3,1,'published');
INSERT INTO speakers (id,speaker_key,name,photo_url,one_liner,area,job_title,intro_text,personality_text) VALUES (3,'ST0016','平野 一真','/images/speakers/ST0016.webp','直感と比較表を使い分ける。小さな決断は大胆に、大事な判断は慎重に。','久留米エリア','家計・貯蓄相談','堅実な伴走者と言われます。休日は応援チームのアウェイ戦を追いかけ、好きなもののためなら遠征もいといません。小さな決断は思い切りよく、大事な判断は確かめてから動きます。今の楽しみと先の備えを、状況に応じて使い分けます。','人柄は堅実な伴走者。日頃は「気に入った文房具をずっと使う」という一面も。休日はランニングやスポーツ観戦を楽しみます。29歳、仕事では小さな約束も守ることを大切にしています。');
