INSERT INTO speaker_episodes (episode_key,speaker_id,source_type,title,body,axis_id,direction,status) VALUES ('EP0046',3,'self','走ったことのない町のコースへ','休みの日のランニングは、電車で知らない町まで行って走ります。地図で見つけた川沿いの道を、景色を見ながらゆっくり進むのが好きです。',1,1,'published');
INSERT INTO speaker_episodes (episode_key,speaker_id,source_type,title,body,axis_id,direction,status) VALUES ('EP0047',3,'self','締切の日に申し込んだ','マラソン大会の締切が今日だと知って、走ったこともないのに申し込みました。練習の予定は、その夜に立てました。',2,1,'published');
INSERT INTO speaker_episodes (episode_key,speaker_id,source_type,title,body,axis_id,direction,status) VALUES ('EP0048',3,'self','入った日に、よそへ移す','給料が入った日に、使わない分を先に別のところへ移します。移したお金は、その月はもう無いものとして数えています。',3,-1,'published');
INSERT INTO questions (id,question_no,axis_id,direction,episode_text,summary,source_type,source_label,speaker_id) VALUES (1,1,1,1,'アウェイ戦が遠くの街に決まった日、宿も決めないうちに飛行機を取りました。朝いちばんの便でも、着けば元気になります。','試合より先に飛行機を取る','self','村上 一樹さんの話',NULL);
INSERT INTO questions (id,question_no,axis_id,direction,episode_text,summary,source_type,source_label,speaker_id) VALUES (2,2,1,1,'好きな人の追加公演が決まると、その日の予定をぜんぶ後ろにずらします。遠くても、行かなかった日のことを考えるほうが嫌なので。','追加公演が出たら予定を動かす','self','鈴木 真由さんの話',NULL);
INSERT INTO questions (id,question_no,axis_id,direction,episode_text,summary,source_type,source_label,speaker_id) VALUES (3,3,1,-1,'駅前に新しい花屋ができても、月に一度の花は前から同じ店で買います。どちらがいいか見に行ったことさえありません。','新しい花屋は、見にも行かない','self','山本 瑞希さんの話',NULL);
INSERT INTO questions (id,question_no,axis_id,direction,episode_text,summary,source_type,source_label,speaker_id) VALUES (4,4,1,-1,'誕生日は、新しい店より近所の洋食屋。座ると「いつもの？」と聞かれるから、メニューはほとんど開かない。','誕生日も、近所の洋食屋','self','中村 さくらさんの話',2);
INSERT INTO questions (id,question_no,axis_id,direction,episode_text,summary,source_type,source_label,speaker_id) VALUES (5,5,2,1,'部屋を広くしたいと思った日に、大きな本棚を買いました。どこに置くかは、届いてから考えました。','本棚を買ってから間取りを考えた','self','太田 悠人さんの話',1);
INSERT INTO questions (id,question_no,axis_id,direction,episode_text,summary,source_type,source_label,speaker_id) VALUES (6,6,2,1,'百キロの大会の締切が今日だと知って、走れるかを考える前に申し込みました。練習の予定は、その夜に立てました。','締切の日に申し込んだ','self','平野 一真さんの話',3);
INSERT INTO questions (id,question_no,axis_id,direction,episode_text,summary,source_type,source_label,speaker_id) VALUES (7,7,2,-1,'洗濯機を見に行く日、測った寸法を三つメモして持っていきました。「入りますよ」と言われても、持ってきた紙を開きます。','寸法を三つメモして売場へ','self','山本 瑞希さんの話',NULL);
INSERT INTO questions (id,question_no,axis_id,direction,episode_text,summary,source_type,source_label,speaker_id) VALUES (8,8,2,-1,'家族のスマホを替える前に、三社の料金を一枚の紙に並べました。家族には「もう決めていい」と言われましたが、もう少し見ていました。','三社の料金を一枚の紙に','self','村上 一樹さんの話',NULL);
INSERT INTO questions (id,question_no,axis_id,direction,episode_text,summary,source_type,source_label,speaker_id) VALUES (9,9,3,1,'好きなバンドの記念公演で、ステージに近い席を取りました。その月はずっと家で食べていましたが、後悔はしていません。','その席は、今年しかない','self','太田 悠人さんの話',1);
INSERT INTO questions (id,question_no,axis_id,direction,episode_text,summary,source_type,source_label,speaker_id) VALUES (10,10,3,1,'前から気になっていた店に、誕生日だからと入りました。いつもより高い一皿でしたが、その月はそれで十分でした。','気になっていた店に、誕生日に','self','遠藤 美咲さんの話',NULL);
INSERT INTO questions (id,question_no,axis_id,direction,episode_text,summary,source_type,source_label,speaker_id) VALUES (11,11,3,-1,'給料が入った日に、使わない分を先に別のところへ移します。移したお金は、その月はもう無いものとして数えています。','入った日に、よそへ移す','self','平野 一真さんの話',3);
INSERT INTO questions (id,question_no,axis_id,direction,episode_text,summary,source_type,source_label,speaker_id) VALUES (12,12,3,-1,'冷蔵庫が急に壊れて困った年から、修理のためのお金を毎月よけています。そのぶん今月の外食は一回減りますが、戻すつもりはありません。','壊れていないうちから、よけておく','self','鈴木 真由さんの話',NULL);
